using System;using System.Linq;using System.Reflection;using System.Windows.Forms;class UiGuideTests{static int n;static void C(bool b,string m){if(!b)throw new Exception(m);n++;}static Control Find(Control p,string name){foreach(Control c in p.Controls){if(c.Name==name)return c;var f=Find(c,name);if(f!=null)return f;}return null;}[STAThread]static void Main(){var a=Assembly.LoadFrom("Trainer.exe");using(var p=(Control)Activator.CreateInstance(a.GetType("SavePanel"),new object[]{false})){var guide=Find(p,"walkthroughPanel");var toggle=Find(p,"walkthroughToggle") as CheckBox;C(guide!=null&&toggle!=null,"independent walkthrough controls");C(!toggle.Checked&&!guide.Visible,"default collapsed");foreach(var name in new[]{"saveDirectory","saveInspect","saveBackup","saveRepair","saveRestore"})C(Find(p,name)!=null&&Find(p,name).Visible,"save controls always visible "+name);toggle.Checked=true;C(guide.Visible,"explicit reveal");toggle.Checked=false;C(!guide.Visible,"collapse again");C(Find(p,"saveBackup").Visible,"collapse keeps operations");}Console.WriteLine("PASS "+n+" spoiler/UI assertions");}}
